// Verify Kubernetes entities are being discovered (smartscape topology)
smartscapeNodes "K8S_CLUSTER"
| fields entity.name = name, lifetime
| sort lifetime desc

// Legacy alternative (deprecated for new content):
// fetch dt.entity.kubernetes_cluster
// | fields entity.name, lifetime
// | sort lifetime desc

// Check if container metrics are flowing
timeseries cpu = avg(dt.kubernetes.container.cpu_usage), from:-1h
| limit 1

// ActiveGates that stopped reporting — last seen more than 2 h ago
// Uses Smartscape node lifetimes (no bytes scanned). from:-7d is required: without it only nodes
// seen in the default window are returned, so a long-silent ActiveGate is invisible.
// A re-created ActiveGate pod gets a new node with the same name, so group by name and take the
// latest last-seen time — a name with a current instance drops out.
// This replaces a dt.davis.events filter on "ACTIVEGATE" / "AGENT_CONNECTION" event types, which
// matched nothing over 30 days on the validation tenant (10/02/2026): no such event types exist there.
smartscapeNodes "ACTIVEGATE", from:-7d
| summarize {lastSeen = max(lifetime[end]), instances = count()}, by:{name}
| filter lastSeen < now() - 2h
| sort lastSeen desc

// Hosts with gaps in CPU reporting (OneAgent interruptions)
// arraySize counts empty buckets too, so count only the non-null ones.
timeseries hostCpu = avg(dt.host.cpu.usage), from:-6h, by:{dt.entity.host}
| fieldsAdd buckets = arraySize(hostCpu), reported = arraySize(arrayRemoveNulls(hostCpu))
| fieldsAdd completeness = round(100.0 * reported / buckets, decimals: 1)
| filter completeness < 95.0
| fieldsAdd hostName = entityName(dt.entity.host, type:"dt.entity.host")
| fields hostName, completeness, reported, buckets
| sort completeness asc
// A host that stopped reporting entirely drops out of timeseries altogether —
// cross-check smartscapeNodes "HOST" for hosts with no series.
